CREATE TABLE AUD_PROJECT_BUNDLES (
    BUNDLE_ID VARCHAR(64) PRIMARY KEY,
    MANIFEST TEXT NOT NULL,
    CREATED_BY VARCHAR NOT NULL,
    CREATED_AT TIMESTAMP NOT NULL
);
CREATE INDEX ix_project_bundles_latest ON AUD_PROJECT_BUNDLES (CREATED_AT DESC,BUNDLE_ID DESC);
ALTER TABLE AUD_PIPELINES_RUN_LOG ADD COLUMN BUNDLE_ID VARCHAR(64) REFERENCES AUD_PROJECT_BUNDLES(BUNDLE_ID);
ALTER TABLE AUD_PIPELINES_RUN_LOG ADD COLUMN METADATA_VERSION VARCHAR(64);
ALTER TABLE AUD_PIPELINES_RUN_LOG ADD COLUMN METADATA_SNAPSHOT TEXT;
UPDATE AUD_PIPELINES_RUN_LOG AS original
SET (METADATA_SNAPSHOT,METADATA_VERSION) = (WITH image AS (WITH own_tasks AS (SELECT TASK_ID AS task_id FROM CFG_TASKS WHERE PIPELINE_ID=original.PIPELINE_ID),
wanted_tasks AS (SELECT TASK_ID AS task_id FROM own_tasks UNION SELECT DEPENDS_ON_TASK_ID AS task_id FROM CFG_TASK_DEPENDENCY WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks)),
wanted_pipelines AS (SELECT original.PIPELINE_ID AS pipeline_id UNION SELECT PIPELINE_ID AS pipeline_id FROM CFG_TASKS WHERE TASK_ID IN (SELECT TASK_ID FROM wanted_tasks) UNION SELECT DEPENDS_ON_PIPELINE_ID AS pipeline_id FROM CFG_PIPELINE_DEPENDENCY WHERE PIPELINE_ID=original.PIPELINE_ID),
wanted_tables AS (SELECT TARGET_TABLE_ID AS table_id FROM CFG_TASKS WHERE TASK_ID IN (SELECT TASK_ID FROM wanted_tasks) UNION SELECT TARGET_TABLE_ID AS table_id FROM CFG_BUSINESS_RULES WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks))
SELECT CAST(json_object('CFG_PIPELINES',json_object('columns',json('["pipeline_id", "pipeline_code", "pipeline_name", "description", "run_schedule", "sla_in_hours", "refresh_type", "active_flag", "pipeline_parameters", "created_by", "create_date", "updated_by", "updated_date", "schedule_timezone", "catchup", "max_catchup_runs", "overlap_policy", "schedule_start_date", "max_parallel_tasks", "priority"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('pipeline_id',r.pipeline_id,'pipeline_code',r.pipeline_code,'pipeline_name',r.pipeline_name,'description',r.description,'run_schedule',r.run_schedule,'sla_in_hours',r.sla_in_hours,'refresh_type',r.refresh_type,'active_flag',r.active_flag,'pipeline_parameters',r.pipeline_parameters,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date,'schedule_timezone',r.schedule_timezone,'catchup',r.catchup,'max_catchup_runs',r.max_catchup_runs,'overlap_policy',r.overlap_policy,'schedule_start_date',r.schedule_start_date,'max_parallel_tasks',r.max_parallel_tasks,'priority',r.priority)) FROM (SELECT * FROM CFG_PIPELINES WHERE PIPELINE_ID IN (SELECT PIPELINE_ID FROM wanted_pipelines) ORDER BY pipeline_id) r),'[]'))),
'CFG_TASKS',json_object('columns',json('["task_id", "task_code", "task_type", "pipeline_id", "handler", "run_condition", "run_condition_count", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "target_table_id", "target_active_flag"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('task_id',r.task_id,'task_code',r.task_code,'task_type',r.task_type,'pipeline_id',r.pipeline_id,'handler',r.handler,'run_condition',r.run_condition,'run_condition_count',r.run_condition_count,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date,'target_table_id',r.target_table_id,'target_active_flag',r.target_active_flag)) FROM (SELECT * FROM CFG_TASKS WHERE TASK_ID IN (SELECT TASK_ID FROM wanted_tasks) ORDER BY task_id) r),'[]'))),
'CFG_TASK_PARAMETERS',json_object('columns',json('["task_parameter_id", "task_id", "parameter_name", "parameter_value", "active_flag", "created_by", "create_date", "updated_by", "updated_date"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('task_parameter_id',r.task_parameter_id,'task_id',r.task_id,'parameter_name',r.parameter_name,'parameter_value',r.parameter_value,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date)) FROM (SELECT * FROM CFG_TASK_PARAMETERS WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks) ORDER BY task_parameter_id) r),'[]'))),
'CFG_TASK_DEPENDENCY',json_object('columns',json('["task_dependency_id", "pipeline_id", "task_id", "depends_on_pipeline_id", "depends_on_task_id", "dependency_type", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "consume_repairs"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('task_dependency_id',r.task_dependency_id,'pipeline_id',r.pipeline_id,'task_id',r.task_id,'depends_on_pipeline_id',r.depends_on_pipeline_id,'depends_on_task_id',r.depends_on_task_id,'dependency_type',r.dependency_type,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date,'consume_repairs',r.consume_repairs)) FROM (SELECT * FROM CFG_TASK_DEPENDENCY WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks) ORDER BY task_dependency_id) r),'[]'))),
'CFG_PIPELINE_DEPENDENCY',json_object('columns',json('["pipeline_dependency_id", "pipeline_id", "depends_on_pipeline_id", "dependency_type", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "consume_repairs"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('pipeline_dependency_id',r.pipeline_dependency_id,'pipeline_id',r.pipeline_id,'depends_on_pipeline_id',r.depends_on_pipeline_id,'dependency_type',r.dependency_type,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date,'consume_repairs',r.consume_repairs)) FROM (SELECT * FROM CFG_PIPELINE_DEPENDENCY WHERE PIPELINE_ID=original.PIPELINE_ID ORDER BY pipeline_dependency_id) r),'[]'))),
'CFG_BUSINESS_RULES',json_object('columns',json('["business_rule_id", "business_rule_name", "pipeline_id", "task_id", "business_rule_sql", "business_rule_type", "business_rule_key_column", "sequence_number", "active_flag", "created_by", "create_date", "updated_by", "updated_date", "target_table_id"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('business_rule_id',r.business_rule_id,'business_rule_name',r.business_rule_name,'pipeline_id',r.pipeline_id,'task_id',r.task_id,'business_rule_sql',r.business_rule_sql,'business_rule_type',r.business_rule_type,'business_rule_key_column',r.business_rule_key_column,'sequence_number',r.sequence_number,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date,'target_table_id',r.target_table_id)) FROM (SELECT * FROM CFG_BUSINESS_RULES WHERE TASK_ID IN (SELECT TASK_ID FROM own_tasks) ORDER BY business_rule_id) r),'[]'))),
'CFG_TABLES',json_object('columns',json('["table_id", "catalog_name", "schema_name", "table_name", "object_kind", "active_flag", "created_by", "create_date", "updated_by", "updated_date"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('table_id',r.table_id,'catalog_name',r.catalog_name,'schema_name',r.schema_name,'table_name',r.table_name,'object_kind',r.object_kind,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date)) FROM (SELECT * FROM CFG_TABLES WHERE TABLE_ID IN (SELECT TABLE_ID FROM wanted_tables) ORDER BY table_id) r),'[]'))),
'CFG_COLUMNS',json_object('columns',json('["column_id", "table_id", "column_name", "data_type", "column_position", "is_nullable", "active_flag", "created_by", "create_date", "updated_by", "updated_date"]'),'rows',json(COALESCE((SELECT json_group_array(json_object('column_id',r.column_id,'table_id',r.table_id,'column_name',r.column_name,'data_type',r.data_type,'column_position',r.column_position,'is_nullable',r.is_nullable,'active_flag',r.active_flag,'created_by',r.created_by,'create_date',r.create_date,'updated_by',r.updated_by,'updated_date',r.updated_date)) FROM (SELECT * FROM CFG_COLUMNS WHERE TABLE_ID IN (SELECT TABLE_ID FROM wanted_tables) ORDER BY column_id) r),'[]')))) AS text) AS snapshot) SELECT CAST(snapshot AS text) AS snapshot,etl_craft_sha256(snapshot) AS version FROM image)
WHERE STATUS IN ('QUEUED','IN-PROGRESS');
CREATE TRIGGER trg_actor_guard_aud_project_bundles_insert BEFORE INSERT ON AUD_PROJECT_BUNDLES
BEGIN
 SELECT CASE WHEN etl_craft_actor() IS NULL THEN RAISE(ABORT, 'AUD_PROJECT_BUNDLES is written only by etl-craft') END;
END;
CREATE TRIGGER trg_actor_guard_aud_project_bundles_update BEFORE UPDATE ON AUD_PROJECT_BUNDLES
BEGIN
 SELECT CASE WHEN etl_craft_actor() IS NULL THEN RAISE(ABORT, 'AUD_PROJECT_BUNDLES is written only by etl-craft') END;
 SELECT CASE WHEN etl_craft_purpose() <> 'retention' THEN RAISE(ABORT, 'AUD_PROJECT_BUNDLES is append-only; use etl-craft retention') END;
END;
CREATE TRIGGER trg_actor_guard_aud_project_bundles_delete BEFORE DELETE ON AUD_PROJECT_BUNDLES
BEGIN
 SELECT CASE WHEN etl_craft_actor() IS NULL THEN RAISE(ABORT, 'AUD_PROJECT_BUNDLES is written only by etl-craft') END;
 SELECT CASE WHEN etl_craft_purpose() <> 'retention' THEN RAISE(ABORT, 'AUD_PROJECT_BUNDLES is append-only; use etl-craft retention') END;
END;
CREATE TRIGGER trg_run_definition_immutable BEFORE UPDATE OF BUNDLE_ID,METADATA_VERSION,METADATA_SNAPSHOT ON AUD_PIPELINES_RUN_LOG
WHEN OLD.METADATA_SNAPSHOT IS NOT NULL AND (NEW.BUNDLE_ID IS NOT OLD.BUNDLE_ID OR NEW.METADATA_VERSION IS NOT OLD.METADATA_VERSION OR NEW.METADATA_SNAPSHOT IS NOT OLD.METADATA_SNAPSHOT)
BEGIN SELECT RAISE(ABORT, 'run definition is immutable; start a new run'); END;
